/* adi.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "adi.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	u[i][j] =  (DATA_TYPE)(i + n-j) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */

static 
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n)) 

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("u");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, u[i][j]);
    }
  POLYBENCH_DUMP_END("u");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Based on a Fortran code fragment from Figure 5 of
 * "Automatic Data and Computation Decomposition on Distributed Memory Parallel Computers"
 * by Peizong Lee and Zvi Meir Kedem, TOPLAS, 2002
 */
static
void kernel_adi[[gnu::flatten, gnu::noinline]](int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  /* Precompute grid and time-step related scalars. */
  const DATA_TYPE one  = SCALAR_VAL(1.0);
  const DATA_TYPE two  = SCALAR_VAL(2.0);
  const DATA_TYPE zero = SCALAR_VAL(0.0);

  DX = one / (DATA_TYPE)_PB_N;
  DY = one / (DATA_TYPE)_PB_N;
  DT = one / (DATA_TYPE)_PB_TSTEPS;

  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);

  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  /* Coefficients for the tridiagonal systems. */
  a = -mul1 /  SCALAR_VAL(2.0);
  b = one + mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = one + mul2;
  f = d;

  /* Frequently used constants (computed once to avoid redundant flops). */
  const DATA_TYPE one_plus_2d = one + two * d;
  const DATA_TYPE one_plus_2a = one + two * a;

  /* Cache _PB_N locally to avoid repeated macro expansion and enable
     better compiler optimization. */
  const int nn = _PB_N;

  for (t = 1; t <= _PB_TSTEPS; t++) {
    /* --------------------------------------------------------------------
     * Column sweep
     *
     * Original code performs, for each column i, a forward sweep and a
     * backward substitution along j (vertical direction). That results
     * in poor spatial locality for accesses to u and v, because in C
     * the first index is the row (y) and the second is the column (x).
     *
     * Here we:
     *   1. Separate boundary initialization from the Thomas algorithm.
     *   2. Iterate with j as the outer loop and i as the inner loop for
     *      the forward and backward sweeps.
     *
     * This reordering:
     *   - Preserves all true dependences: each (i, j) still depends only
     *     on (i, j-1) or (i, j+1), which are computed in previous
     *     iterations of the outer j-loop.
     *   - Greatly improves spatial locality of u[j][*] and v[j][*]
     *     (they are now traversed along contiguous memory).
     *   - Enables effective vectorization across i (no loop-carried
     *     dependences in the inner i-loops).
     * ------------------------------------------------------------------*/

    /* Top boundary conditions and initial p,q values (j = 0). */
    for (i = 1; i < nn - 1; i++) {
      v[0][i] = one;
      p[i][0] = zero;
      q[i][0] = v[0][i];
    }

    /* Forward sweep along columns (solving tridiagonal systems). 
       j is the "line coordinate" and i indexes independent systems. */
    for (j = 1; j < nn - 1; j++) {
      const DATA_TYPE *restrict u_j = u[j]; /* Current row of u. */

      /* Each iteration over i is independent -> safe to vectorize. */
#pragma GCC ivdep
      for (i = 1; i < nn - 1; i++) {
        const DATA_TYPE denom     = a * p[i][j - 1] + b;
        const DATA_TYPE inv_denom = one / denom; /* Reduces two divides to one. */

        /* p[i][j] = -c / denom; q[i][j] = numer / denom;
           Using inv_denom slightly reorders floating-point operations but
           is algebraically equivalent and typically faster. */
        p[i][j] = -c * inv_denom;

        const DATA_TYPE rhs =
          -d * u_j[i - 1] +
          one_plus_2d * u_j[i] -
          f * u_j[i + 1] -
          a * q[i][j - 1];

        q[i][j] = rhs * inv_denom;
      }
    }

    /* Bottom boundary conditions for v. */
    for (i = 1; i < nn - 1; i++) {
      v[nn - 1][i] = one;
    }

    /* Backward substitution for v, now with j as the outer loop to get
       unit-stride access along rows v[j][*]. */
    for (j = nn - 2; j >= 1; j--) {
      DATA_TYPE       *restrict v_j   = v[j];
      const DATA_TYPE *restrict v_jp1 = v[j + 1];

      /* Again, each i is independent -> vectorizable. */
#pragma GCC ivdep
      for (i = 1; i < nn - 1; i++) {
        v_j[i] = p[i][j] * v_jp1[i] + q[i][j];
      }
    }

    /* --------------------------------------------------------------------
     * Row sweep
     *
     * The original row sweep already has good spatial locality for both
     * v and u because it traverses entire rows (inner loop on j).
     * We keep the original traversal order, but:
     *   - Factor out row pointers for u, v, p, q to reduce indexing
     *     overhead and make aliasing clearer to the compiler.
     *   - Reuse the "one_plus_2a" constant precomputed above.
     *   - Share the denominator between p and q via its reciprocal.
     * ------------------------------------------------------------------*/
    for (i = 1; i < nn - 1; i++) {
      DATA_TYPE *restrict u_i   = u[i];
      DATA_TYPE *restrict p_i   = p[i];
      DATA_TYPE *restrict q_i   = q[i];
      DATA_TYPE *restrict v_im1 = v[i - 1];
      DATA_TYPE *restrict v_i   = v[i];
      DATA_TYPE *restrict v_ip1 = v[i + 1];

      u_i[0] = one;
      p_i[0] = zero;
      q_i[0] = u_i[0];

      for (j = 1; j < nn - 1; j++) {
        const DATA_TYPE denom2     = d * p_i[j - 1] + e;
        const DATA_TYPE inv_denom2 = one / denom2;

        /* p[i][j] = -f / denom2; q[i][j] = numer / denom2. */
        p_i[j] = -f * inv_denom2;

        const DATA_TYPE rhs2 =
          -a * v_im1[j] +
          one_plus_2a * v_i[j] -
          c * v_ip1[j] -
          d * q_i[j - 1];

        q_i[j] = rhs2 * inv_denom2;
      }

      u_i[nn - 1] = one;
      for (j = nn - 2; j >= 1; j--) {
        u_i[j] = p_i[j] * u_i[j + 1] + q_i[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(u));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_adi (tsteps, n, POLYBENCH_ARRAY(u), POLYBENCH_ARRAY(v), POLYBENCH_ARRAY(p), POLYBENCH_ARRAY(q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(u)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(u);
  POLYBENCH_FREE_ARRAY(v);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(q);

  return 0;
}
