   * allocation pattern, but the optimized kernel treats them as unused
   * scratch storage. All computations that used p[i][j]/q[i][j] are now
   * performed in small 1D temporaries p_tmp/q_tmp, and only u is part of
   * the live-out data (as in the original benchmark).
   */
  (void)p;
  (void)q;
  (void)tsteps; /* _PB_TSTEPS is derived from tsteps via PolyBench macros. */
  (void)n;      /* _PB_N is derived from n via PolyBench macros.          */

  /* Problem sizes as plain integers for local use. */
  const int nPB = _PB_N;
  const int tPB = _PB_TSTEPS;

  /* Frequently used scalar constants. */
  const DATA_TYPE one  = SCALAR_VAL(1.0);
  const DATA_TYPE zero = SCALAR_VAL(0.0);
  const DATA_TYPE two  = SCALAR_VAL(2.0);

  /* Spatial and temporal step sizes. */
  DATA_TYPE DX = one / (DATA_TYPE)nPB;
  DATA_TYPE DY = one / (DATA_TYPE)nPB;
  DATA_TYPE DT = one / (DATA_TYPE)tPB;

  /* PDE-related constants. */
  const DATA_TYPE B1   = SCALAR_VAL(2.0);
  const DATA_TYPE B2   = one;

  const DATA_TYPE mul1 = B1 * DT / (DX * DX);
  const DATA_TYPE mul2 = B2 * DT / (DY * DY);

  const DATA_TYPE a = -mul1 / two;
  const DATA_TYPE b = one + mul1;
  const DATA_TYPE c = a;
  const DATA_TYPE d = -mul2 / two;
  const DATA_TYPE e = one + mul2;
  const DATA_TYPE f = d;

  /* Small helper constants to avoid recomputing (1 + 2*a) and (1 + 2*d)
   * in the innermost loops.
   */
  const DATA_TYPE one_plus_2d = one + two * d;
  const DATA_TYPE one_plus_2a = one + two * a;

  /* Temporary 1D buffers for the tridiagonal solves in both sweeps.
   * Size nPB is sufficient, we only use indices 0..nPB-2.
   * Reusing these buffers avoids writing the large 2D p/q work arrays,
   * significantly reducing memory traffic while preserving the values
   * computed for u and v.
   */
  DATA_TYPE p_tmp[_PB_N];
  DATA_TYPE q_tmp[_PB_N];

#pragma scop
  for (int t = 1; t <= tPB; ++t) {

    /* --------------------------------------------------------------
     * Column Sweep
     * Solve tridiagonal systems along the j-dimension for each
     * interior column i, updating v(:, i).
     * -------------------------------------------------------------- */

    /* Top boundary condition for all interior columns. */
    for (int i = 1; i < nPB - 1; ++i) {
      v[0][i] = one;
    }

    /* Process each interior column independently. */
    for (int i = 1; i < nPB - 1; ++i) {
      /* Forward sweep for column i. */
      p_tmp[0] = zero;
      q_tmp[0] = v[0][i];  /* = 1.0 */

      for (int j = 1; j < nPB - 1; ++j) {
        DATA_TYPE denom = a * p_tmp[j - 1] + b;

        /* Right-hand side of the tridiagonal system, using neighbors of u
         * in the i-direction at fixed j.
         */
        DATA_TYPE rhs =
          (-d * u[j][i - 1]) +
          (one_plus_2d * u[j][i]) -
          (f * u[j][i + 1]) -
          (a * q_tmp[j - 1]);

        p_tmp[j] = -c / denom;
        q_tmp[j] = rhs / denom;
      }

      /* Backward substitution for column i. */
      v[nPB - 1][i] = one;
      for (int j = nPB - 2; j >= 1; --j) {
        v[j][i] = p_tmp[j] * v[j + 1][i] + q_tmp[j];
      }
    }

    /* --------------------------------------------------------------
     * Row Sweep
     * Solve tridiagonal systems along the j-dimension for each
     * interior row i, updating u(i, :).
     * -------------------------------------------------------------- */

    for (int i = 1; i < nPB - 1; ++i) {
      u[i][0] = one;

      /* Forward sweep for row i. */
      p_tmp[0] = zero;
      q_tmp[0] = u[i][0];

      /* Row pointers to improve locality and reduce address arithmetic. */
      DATA_TYPE *v_im1 = v[i - 1];
      DATA_TYPE *v_i   = v[i];
      DATA_TYPE *v_ip1 = v[i + 1];

      for (int j = 1; j < nPB - 1; ++j) {
        DATA_TYPE denom = d * p_tmp[j - 1] + e;

        /* Right-hand side using neighbors of v in the i-direction at
         * fixed j, mirroring the original formulation.
         */
        DATA_TYPE rhs =
          (-a * v_im1[j]) +
          (one_plus_2a * v_i[j]) -
          (c * v_ip1[j]) -
          (d * q_tmp[j - 1]);

        p_tmp[j] = -f / denom;
        q_tmp[j] = rhs / denom;
      }

      /* Backward substitution for row i. */
      u[i][nPB - 1] = one;
      for (int j = nPB - 2; j >= 1; --j) {
        u[i][j] = p_tmp[j] * u[i][j + 1] + q_tmp[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(u));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_adi (tsteps, n, POLYBENCH_ARRAY(u), POLYBENCH_ARRAY(v),
              POLYBENCH_ARRAY(p), POLYBENCH_ARRAY(q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(u)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(u);
  POLYBENCH_FREE_ARRAY(v);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(q);

