  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 / two;
  b = one + mul1;
  c = a;
  d = -mul2 / two;
  e = one + mul2;
  f = d;

  /* Precompute coefficients that do not change across the time loop.
     This saves work in the inner loops and improves instruction-level
     parallelism. */
  const DATA_TYPE col_central = one + two * d; /* 1 + 2*d */
  const DATA_TYPE row_central = one + two * a; /* 1 + 2*a */

  for (int t = 1; t <= tsteps_; t++) {

    /* Column sweep.
     *
     * Each column index 'i' is independent in this sweep, so the outer
     * loop can be parallelized.  The inner 'j' loop is a tridiagonal
     * solve with loop-carried dependences and must remain sequential.
     */
#ifdef _OPENMP
# pragma omp parallel for ADI_OMP_SCHEDULE if (n_ >= ADI_OMP_MIN_N)
#endif
    for (int i = 1; i < n_ - 1; i++) {
      /* Forward elimination along j. */
      v_[0][i] = one;
      p_[i][0] = zero;
      q_[i][0] = v_[0][i];

      for (int j = 1; j < n_ - 1; j++) {
        const DATA_TYPE p_prev = p_[i][j - 1];
        const DATA_TYPE q_prev = q_[i][j - 1];

        /* Common denominator used by both p and q updates. */
        const DATA_TYPE denom = a * p_prev + b;

        /* Load the three-point stencil of u along the current column. */
        const DATA_TYPE u_j_im1 = u_[j][i - 1];
        const DATA_TYPE u_j_i   = u_[j][i    ];
        const DATA_TYPE u_j_ip1 = u_[j][i + 1];

