           divisions.  This is mathematically equivalent but can differ
           slightly in floating-point rounding compared to the original
           code that performed two separate divisions. */
        const DATA_TYPE inv_denom = one / denom;
        p_[i][j] = -c * inv_denom;
        q_[i][j] =  numer * inv_denom;
#else
        p_[i][j] = -c / denom;
        q_[i][j] =  numer / denom;
#endif
