     *
     * Each row index 'i' is independent in this sweep as well, so the
     * outer loop can be parallelized similarly to the column sweep.
     */
#ifdef _OPENMP
# pragma omp parallel for ADI_OMP_SCHEDULE if (n_ >= ADI_OMP_MIN_N)
#endif
    for (int i = 1; i < n_ - 1; i++) {
      /* Forward elimination along j. */
      u_[i][0] = one;
      p_[i][0] = zero;
      q_[i][0] = u_[i][0];

