/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimization overview
   ---------------------
   The original kernel processes the "column sweep" with the outer loop
   on the column index and the inner loop on the row index. Since the
   arrays are laid out in row-major order, this leads to strided access
   to u and v during that sweep.

   The key optimizations below are:
   - Restructure the column sweep to iterate row-major:
       * initialize all columns' boundary values first,
       * perform forward elimination with outer loop on j (row) and
         inner loop on i (column),
       * perform backward substitution likewise with outer loop on j.
     This preserves all data dependencies (they are only along j for
     fixed i) but makes accesses to u and v cache-friendly.
   - Use contiguous 1D views (u_data, v_data, p_data, q_data) plus
     explicit index arithmetic to reduce repeated index computations.
   - Precompute small invariant coefficients (e.g., 1 + 2*d) outside
     the hot loops.
   - Use restrict-qualified pointers within the kernel to help the
     compiler with alias analysis (arrays are known not to overlap).

   The row sweep already has good row-major access, so it is kept
   structurally identical, with only minor index-optimization changes.
 */
static
void kernel_adi[[gnu::flatten, gnu::noinline]](int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  /* Basic scalar constants. */
  const DATA_TYPE one = SCALAR_VAL(1.0);
  const DATA_TYPE two = SCALAR_VAL(2.0);

  /* Use dynamic problem size to compute step sizes. */
  DX = one / (DATA_TYPE)n;
  DY = one / (DATA_TYPE)n;
  DT = one / (DATA_TYPE)tsteps;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 /  SCALAR_VAL(2.0);
  b = one + mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = one + mul2;
  f = d;

  /* Coefficients that are reused many times. */
  const DATA_TYPE one_plus_2d = one + two * d;
  const DATA_TYPE one_plus_2a = one + two * a;

  /* The PolyBench 2D arrays are allocated as single contiguous
     n-by-n blocks in row-major order. Expose this layout explicitly
     for cheaper index arithmetic and better optimization. */
  DATA_TYPE * restrict u_data = &u[0][0];
  DATA_TYPE * restrict v_data = &v[0][0];
  DATA_TYPE * restrict p_data = &p[0][0];
  DATA_TYPE * restrict q_data = &q[0][0];

  const int N = n;
  const int T = tsteps;
  const int stride = n; /* leading dimension (number of columns) */

  for (t = 0; t < T; ++t)
  {
    /* ============================================================
       Column sweep: solve tridiagonal systems along the j-direction
       ============================================================ */

    /* 1) Boundary conditions and initial values for p and q.
          This corresponds to the "top" of each column. */
    for (i = 1; i < N - 1; ++i)
    {
      v[0][i] = one;
      p[i][0] = SCALAR_VAL(0.0);
      q[i][0] = v[0][i];
    }

    /* 2) Forward elimination:
          Compute p[i][j] and q[i][j] for all 1 <= j <= N-2, 1 <= i <= N-2.

       Original code used:
         for i: 1..N-2
           for j: 1..N-2
             p[i][j] = ...
             q[i][j] = ...

       Dependencies are along j for each fixed i:
         p[i][j] depends on p[i][j-1]
         q[i][j] depends on q[i][j-1] and u[j][i-1..i+1]

       Therefore, we can legally reorder the iteration space to:
         for j: 1..N-2
           for i: 1..N-2
       as long as we still process increasing j for each i, which we do. */
    for (j = 1; j < N - 1; ++j)
    {
      /* Row base for u[j][*] in the linear storage. */
      const size_t u_row_base = (size_t)j * (size_t)stride;

      /* Indices into u for i = 1 at this row:
           u_left   = u[j][0]
           u_center = u[j][1]
           u_right  = u[j][2]
         As i increments, these indices will be incremented by 1. */
      size_t u_left_idx   = u_row_base + (size_t)0;
      size_t u_center_idx = u_row_base + (size_t)1;
      size_t u_right_idx  = u_row_base + (size_t)2;

      /* Indices into p and q for (i, j-1) and (i, j) when i = 1:
           pq_prev_idx = index of p[1][j-1], q[1][j-1]
           pq_curr_idx = index of p[1][j],   q[1][j]
         As i increments, these indices will be incremented by "stride"
         (moving to the next row i+1 at the same column j). */
      size_t pq_prev_idx = (size_t)1 * (size_t)stride + (size_t)(j - 1);
      size_t pq_curr_idx = (size_t)1 * (size_t)stride + (size_t)j;

      for (i = 1; i < N - 1; ++i)
      {
        const DATA_TYPE p_prev = p_data[pq_prev_idx];
        const DATA_TYPE q_prev = q_data[pq_prev_idx];

        /* Denominator shared between p and q updates;
           computing it once preserves floating point semantics. */
        const DATA_TYPE denom = a * p_prev + b;

        /* p[i][j] update. */
        p_data[pq_curr_idx] = -c / denom;

        /* q[i][j] update uses three neighbors in u at row j and q[i][j-1]. */
        const DATA_TYPE u_left   = u_data[u_left_idx];
        const DATA_TYPE u_center = u_data[u_center_idx];
        const DATA_TYPE u_right  = u_data[u_right_idx];

        const DATA_TYPE num =
          (-d * u_left) +
          (one_plus_2d * u_center) -
          (f * u_right) -
          (a * q_prev);

        q_data[pq_curr_idx] = num / denom;

        /* Move to column (i+1) for all linear indices. */
        pq_prev_idx += (size_t)stride;
        pq_curr_idx += (size_t)stride;
        ++u_left_idx;
        ++u_center_idx;
        ++u_right_idx;
      }
    }

    /* 3) Bottom boundary condition for v. */
    for (i = 1; i < N - 1; ++i)
    {
      v[N - 1][i] = one;
    }

    /* 4) Backward substitution:
          v[j][i] = p[i][j] * v[j+1][i] + q[i][j],
          for j = N-2 .. 1, and 1 <= i <= N-2.

       Original nesting:
         for i: 1..N-2
           v[N-1][i] = 1
           for j: N-2..1
             v[j][i] = ...

       Here we again exploit the fact that dependencies are only along j
       at fixed i and reorder to process row by row:
         for j: N-2..1
           for i: 1..N-2

       This gives row-major access to v (better locality) while leaving
       p and q as temporary data accessed with a stride in i. */
    for (j = N - 2; j >= 1; --j)
    {
      const size_t v_row_base      = (size_t)j * (size_t)stride;
      const size_t v_next_row_base = (size_t)(j + 1) * (size_t)stride;

      /* For i = 1:
           v_curr_idx = index of v[j][1]
           v_next_idx = index of v[j+1][1]
           pq_idx     = index of p[1][j], q[1][j]
         As i increments, v_* indices advance by +1 (within the row),
         and pq_idx advances by +stride (to the next row i+1). */
      size_t v_curr_idx = v_row_base      + (size_t)1;
      size_t v_next_idx = v_next_row_base + (size_t)1;
      size_t pq_idx     = (size_t)1 * (size_t)stride + (size_t)j;

      for (i = 1; i < N - 1; ++i)
      {
        v_data[v_curr_idx] =
          p_data[pq_idx] * v_data[v_next_idx] + q_data[pq_idx];

        ++v_curr_idx;
        ++v_next_idx;
        pq_idx += (size_t)stride;
      }
    }

    /* ============================================================
       Row sweep: solve tridiagonal systems along the i-direction
       ============================================================ */
    for (i = 1; i < N - 1; ++i)
    {
      /* Row pointers to avoid repeated 2D index arithmetic. */
      DATA_TYPE * restrict u_row       = &u[i][0];
      DATA_TYPE * restrict p_row       = &p[i][0];
      DATA_TYPE * restrict q_row       = &q[i][0];
      DATA_TYPE * restrict v_row       = &v[i][0];
      DATA_TYPE * restrict v_row_above = &v[i - 1][0];
      DATA_TYPE * restrict v_row_below = &v[i + 1][0];

      u_row[0] = one;
      p_row[0] = SCALAR_VAL(0.0);
      q_row[0] = u_row[0];

      /* Forward elimination along the row:
           p[i][j] = -f / (d*p[i][j-1] + e)
           q[i][j] = (...) / (d*p[i][j-1] + e)
         with dependencies only on (i, j-1) at fixed i. */
      for (j = 1; j < N - 1; ++j)
      {
        const DATA_TYPE p_prev = p_row[j - 1];
        const DATA_TYPE q_prev = q_row[j - 1];

        const DATA_TYPE denom = d * p_prev + e;

        p_row[j] = -f / denom;

        const DATA_TYPE num =
          (-a * v_row_above[j]) +
          (one_plus_2a * v_row[j]) -
          (c * v_row_below[j]) -
          (d * q_prev);

        q_row[j] = num / denom;
      }

      u_row[N - 1] = one;

      /* Backward substitution along the row:
           u[i][j] = p[i][j] * u[i][j+1] + q[i][j] */
      for (j = N - 2; j >= 1; --j)
      {
        u_row[j] = p_row[j] * u_row[j + 1] + q_row[j];
      }
    }
  }

#pragma endscop
}


